const fs = require('fs');
const { execSync } = require('child_process');
const zlib = require('zlib');

// Use Node's built-in unzip via child process or manual parsing
const AdmZip = require('adm-zip');
const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const doc = zip.readAsText('word/document.xml');
// Extract text from XML
const texts = [];
const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
let m;
while ((m = re.exec(doc)) !== null) texts.push(m[1]);

// Also detect paragraph breaks
const full = doc.replace(/<w:p[ >]/g, '\n<w:p ');
const lines = [];
