    const t = [];
    const re2 = /<w:t[^>]*>([^<]*)<\/w:t>/g;
    let m2;
    while ((m2 = re2.exec(para)) !== null) t.push(m2[1]);
    lines.push(t.join(''));
}
console.log(lines.filter((_, i) => i > 0).join('\n'));
