const fs = require('fs');
const { execSync } = require('child_process');
const path = require('path');
const os = require('os');

// Manual ZIP parsing for .docx
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find central directory entries - look for word/document.xml
// Use a simpler approach: write to tmp and use jar or other available tool
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'docx-'));
fs.writeFileSync(path.join(tmpDir, 'doc.zip'), buf);

try {
  execSync('cd ' + tmpDir + ' && unzip -o doc.zip word/document.xml 2>/dev/null || jar xf doc.zip word/document.xml 2>/dev/null');
  const xml = fs.readFileSync(path.join(tmpDir, 'word/document.xml'), 'utf8');

  const paragraphs = xml.split(/<w:p[ >\/]/);
  const lines = [];
  for (const para of paragraphs) {
    const texts = [];
    const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
    let m;
    while ((m = re.exec(para)) !== null) texts.push(m[1]);
    if (texts.length > 0) lines.push(texts.join(''));
  }
  console.log(lines.join('\n'));
} catch(e) {
  // Fallback: parse ZIP manually
  console.error('Extraction failed:', e.message);
}

execSync('rm -rf ' + tmpDir);
" 2>&1

